package com.earthtrip.platform.adapter.out.persistence.integration;
import com.earthtrip.platform.application.port.out.IntegrationStorePort;import jakarta.persistence.*;import java.time.Instant;import java.util.*;
@Entity @Table(name="integration_sync_jobs")class IntegrationSyncJpaEntity{@Id @Column(name="id",length=36)String id;@Column(name="user_id",length=36)String userId;@Column(name="connection_id",length=36)String connectionId;@Column(name="trip_id",length=36)String tripId;@Column(name="job_type",length=40)String jobType;@Column(name="status",length=30)String status;@Column(name="request_payload",columnDefinition="JSON")String request;@Column(name="result_payload",columnDefinition="JSON")String result;@Column(name="error_code",length=80)String errorCode;@Column(name="attempt_count")int attemptCount;@Column(name="created_at")Instant createdAt;@Column(name="updated_at")Instant updatedAt;@Version @Column(name="version")long version;protected IntegrationSyncJpaEntity(){}IntegrationSyncJpaEntity(IntegrationStorePort.SyncRecord r,String q,String s){id=r.id().toString();userId=r.userId().toString();connectionId=r.connectionId()==null?null:r.connectionId().toString();tripId=r.tripId()==null?null:r.tripId().toString();jobType=r.jobType();createdAt=r.createdAt();apply(r,q,s);}void apply(IntegrationStorePort.SyncRecord r,String q,String s){status=r.status();request=q;result=s;errorCode=r.errorCode();attemptCount=r.attemptCount();updatedAt=r.updatedAt();}IntegrationStorePort.SyncRecord record(Map<String,Object>q,Map<String,Object>s){return new IntegrationStorePort.SyncRecord(UUID.fromString(id),UUID.fromString(userId),connectionId==null?null:UUID.fromString(connectionId),tripId==null?null:UUID.fromString(tripId),jobType,status,q,s,errorCode,attemptCount,createdAt,updatedAt,version);}}
